-- Profiles whose city wasn't found before.
update public.profiles p
   set lat = (public.city_point(p.city)).lat, lng = (public.city_point(p.city)).lng
 where p.lat is null and coalesce(p.city, '') <> ''
   and (public.city_point(p.city)).lat is not null;
